use std::{fs,path::Path};#[path="runtime.rs"]mod result_transition;use result_transition::*;
fn main(){let w=std::env::args().nth(1).unwrap();let w=Path::new(&w);let bytes=fs::read(w.join("input.bin")).unwrap();let mut out=Vec::new();for b in bytes.chunks_exact(7228){let players=std::array::from_fn(|i|b[i*1805..(i+1)*1805].try_into().unwrap());let c=&b[7220..];let frame=u32::from_le_bytes(c[4..8].try_into().unwrap());let p=enter_victory(&players,c[0],c[1],c[2],frame,0).unwrap();out.extend(p.players_after.concat());out.extend([p.flags_after,p.mode_after,p.stage_after]);out.extend(p.frame_after.to_le_bytes());out.extend(p.saved_frame.to_le_bytes());out.push(p.service_calls.len()as u8);for a in p.service_calls{out.extend(a.to_le_bytes())}
assert_eq!(continue_after_win(c[1],c[2]).unwrap(),Some(ResultViewRequest::Victory1863DC));assert_eq!(advance_victory(0,c[1],1).unwrap(),None);assert_eq!(advance_victory(1,c[1],1).unwrap(),Some(ResultViewRequest::Campaign186F19));assert!(matches!(advance_victory(1,c[1],24),Err(ResultTransitionError::EndingSequenceRequired)));}
fs::write(w.join("actual.bin"),out).unwrap();}
